from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data.get("roots", {})
    domains = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        domains.append([None] + versions)

    best_versions = None
    best_vector = None
    for values in product(*domains):
        chosen = {name: version for name, version in zip(names, values)
                  if version is not None}
        if any(name not in chosen or not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue

        edges = {name: [] for name in chosen}
        valid = True
        for name, version in chosen.items():
            row = next(row for row in packages[name] if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if (target not in chosen or
                        not dep["min"] <= chosen[target] <= dep["max"]):
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        pending = list(roots)
        while pending:
            node = pending.pop()
            if node in reachable:
                continue
            if node not in chosen:
                valid = False
                break
            reachable.add(node)
            pending.extend(edges[node])
        if not valid or reachable != set(chosen):
            continue

        active, finished = set(), set()

        def visit(node):
            if node in active:
                return False
            if node in finished:
                return True
            active.add(node)
            if any(not visit(child) for child in edges[node]):
                return False
            active.remove(node)
            finished.add(node)
            return True

        if not all(visit(node) for node in edges):
            continue

        vector = tuple(chosen.get(name, -1) for name in names)
        if best_vector is None or (vector > best_vector if preference == "maximum"
                                   else vector < best_vector):
            best_versions, best_vector = chosen, vector

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def ledger(data):
    winners = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        rank = (event.get("revision", 0), position)
        if event_id not in winners or rank > winners[event_id][0]:
            winners[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(net * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def quota_intervals(data):
    k = data["k"]
    blocked = set(data.get("blocked", []))
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue

        active_ends = []
        valid = True
        for job in sorted(subset, key=lambda row: (row["start"], row["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            active_ends.append(job["end"])
            if len(active_ends) > 2:
                valid = False
                break
        if not valid:
            continue

        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_ids, best_value = selected, value

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    bits = {node: sum(1 << i for i, required_node in enumerate(required)
                      if required_node == node)
            for node in range(data["n"])}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bits[source]
    initial_state = (source, initial_mask, data["coupons"])
    distances = {initial_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}

        for edge in graph[node]:
            departure = max(arrival, edge["open"])
            if departure >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, coupons - 1))
            for duration, remaining in choices:
                next_arrival = departure + duration
                if next_arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bits[next_node]
                next_state = (next_node, next_mask, remaining)
                if next_arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = next_arrival
                    heapq.heappush(queue, (next_arrival, next_node, next_mask, remaining))

    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: dependency_solver(data, "maximum", "ascending"),
    "component_02": lambda data: dependency_solver(data, "minimum", "ascending"),
    "component_03": lambda data: dependency_solver(data, "maximum", "descending"),
    "component_04": lambda data: dependency_solver(data, "minimum", "descending"),
    "component_05": lambda data: dependency_solver(data, "maximum", "ascending"),
    "component_06": ledger,
    "component_07": quota_intervals,
    "component_08": temporal_routes,
}
